import{_ as a,o,c as r,a5 as t}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 55 话 渲染管线：从 DOM 到像素的一帧","description":"","frontmatter":{},"headers":[],"relativePath":"comics/mechanism/EP.55-render-pipeline.md","filePath":"comics/mechanism/EP.55-render-pipeline.md","lastUpdated":1793853676000}'),i={name:"comics/mechanism/EP.55-render-pipeline.md"};function n(l,e,d,c,s,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-55-话-渲染管线-从-dom-到像素的一帧" tabindex="-1">漫画 · 第 55 话 渲染管线：从 DOM 到像素的一帧 <a class="header-anchor" href="#漫画-·-第-55-话-渲染管线-从-dom-到像素的一帧" aria-label="Permalink to &quot;漫画 · 第 55 话 渲染管线：从 DOM 到像素的一帧&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/mechanism/01-render-pipeline">docs/mechanism/01-render-pipeline.md</a> ｜ 原画：<a href="./EP.55-render-pipeline.svg">EP.55-render-pipeline.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她想让卡片“动得高级”，结果一改宽度就掉帧，被管线图上了一课。</li><li><strong>标签君</strong>：结构师。负责把 JS、Style、Layout、Paint、Composite 五段摊开，标出每类属性触发的范围。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱做了一个横向滑动的卡片墙，用 <code>left</code> 逐帧推进，元素一多就卡成 PPT。她怀疑是电脑不行，标签君打开 Performance 面板：每帧都有一条紫色 Layout。换成 <code>transform</code> 后，同样的位移只剩一条绿色 Composite。标签君说：你不是算得慢，是让浏览器每帧重排了一遍。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>卡片墙 120 个元素，每个都改 <code>left</code>。火焰图里 Function 之后紧跟 Layout，Layout 之后又 Paint，一帧主线程被塞满。像素酱的“顺滑”只在小数据量下成立——元素一多，布局成本线性上升，帧预算瞬间击穿。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>一帧的顺序是 JS → Style → Layout → Paint → Composite，后一段依赖前一段。改 <code>width/left/margin</code> 会让布局脏掉，后面全要重跑；改 <code>transform/opacity</code> 只影响合成阶段，布局与绘制结果可以复用。合成线程能独立推进图层变换，所以主线程再忙，纯合成动画也能保持流畅。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>优化不是背属性清单，而是看失效范围：能用 transform 表达的位移就用 transform；必须改尺寸的交互接受一次重排；屏外内容用 <code>content-visibility</code> 跳过。DevTools 里勾选 Layout/Paint，谁在跑一目了然。像素酱把卡片墙改成 transform，掉帧从 38 降到 2。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>管线五段有依赖：改了布局输入，Layout/Paint/Composite 全要重跑。</li><li><code>transform</code> 与 <code>opacity</code> 是合成友好属性，前提是元素具备独立合成条件。</li><li>优化第一步是看 DevTools 的 Layout/Paint 条，不是猜哪个属性快。</li><li><code>will-change</code> 是提示不是命令，常驻会制造图层与显存开销。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把抽屉动画从 <code>left</code> 改成 <code>transform</code> 后，为什么主线程仍然可能卡？</p><p><strong>答</strong>：如果抽屉没有独立合成层，或者动画期间仍在回调里读取布局、修改尺寸，主线程依旧要工作。另外首次栅格化、超大阴影、<code>backdrop-filter</code> 都会把成本转移到绘制/合成。要确认 Layers 面板是否真的提层，并保证动画只碰 transform/opacity。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>三种动画写法对比帧率与长任务：<a href="./../../examples/mechanism/01-render-pipeline">examples/mechanism/01-render-pipeline</a></li><li>打开 DevTools Performance 勾选 Layout/Paint，对照示例切换模式录制。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>位移讲清了，位置却还会“跑偏”。第 56 话《包含块与格式化上下文》——绝对定位参照谁、margin 为什么会穿透父级，一次说透。</p>',22)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
